create table public.note_sections (
  note_id text not null,
  position integer not null,
  anchor text not null,
  title text not null,
  level smallint not null,
  body text not null,
  search tsvector generated always as ((setweight(to_tsvector('public.es'::regconfig, title), 'A'::"char") || setweight(to_tsvector('public.es'::regconfig, body), 'B'::"char"))) stored,
  constraint note_sections_pkey PRIMARY KEY (note_id, "position"),
  constraint note_sections_note_id_fkey FOREIGN KEY (note_id) REFERENCES public.notes(id) ON DELETE CASCADE,
  constraint note_sections_level_check CHECK (((level >= 1) AND (level <= 3)))
);

CREATE INDEX note_sections_search ON public.note_sections USING gin (search);

alter table public.note_sections enable row level security;

grant delete, insert, maintain, references, select, trigger, truncate, update on table public.note_sections to service_role;
